"""
Algorithm 2 -- Compositional Landauer Ledger for Shared Lemmas.

For two proof obligations with a joint law p on pairs of proofs and verifiers f
and g, this computes the separate cost, the joint cost, the input and output
mutual informations, and checks the accounting identity

    separate - joint = I(inputs) - I(outputs),

together with the data-processing bound  I(outputs) <= I(inputs), which makes
the saving non-negative.  Everything runs in one pass over the support of the
joint law plus O(|Y1| * |Y2|) work on the pushforward.
"""

from __future__ import annotations

from dataclasses import dataclass
from math import isclose, log2
from typing import Callable, Dict, Hashable, Iterable, Tuple

Term = Hashable
Joint = Dict[Tuple[Term, Term], float]


def _entropy(values: Iterable[float]) -> float:
    return -sum(v * log2(v) for v in values if v > 0.0)


def _marginals(joint: Joint) -> Tuple[Dict[Term, float], Dict[Term, float]]:
    m1: Dict[Term, float] = {}
    m2: Dict[Term, float] = {}
    for (x, y), w in joint.items():
        m1[x] = m1.get(x, 0.0) + w
        m2[y] = m2.get(y, 0.0) + w
    return m1, m2


def mutual_information(joint: Joint) -> float:
    """I(p) = H(p1) + H(p2) - H(p), computed from the marginals."""
    m1, m2 = _marginals(joint)
    return _entropy(m1.values()) + _entropy(m2.values()) - _entropy(joint.values())


def _cond_entropy(law: Dict[Term, float], h: Callable[[Term], Hashable]) -> float:
    push: Dict[Hashable, float] = {}
    for x, w in law.items():
        push[h(x)] = push.get(h(x), 0.0) + w
    return -sum(w * log2(w / push[h(x)]) for x, w in law.items() if w > 0.0)


@dataclass
class Ledger:
    separate: float
    joint: float
    mutual_in: float
    mutual_out: float

    @property
    def saving(self) -> float:
        return self.separate - self.joint

    @property
    def predicted_saving(self) -> float:
        return self.mutual_in - self.mutual_out


def compositional_ledger(
    joint: Joint,
    f: Callable[[Term], Hashable],
    g: Callable[[Term], Hashable],
) -> Ledger:
    """Full ledger for verifying two obligations separately versus jointly."""
    m1, m2 = _marginals(joint)
    separate = _cond_entropy(m1, f) + _cond_entropy(m2, g)
    pair_map: Callable[[Tuple[Term, Term]], Hashable] = lambda z: (f(z[0]), g(z[1]))
    joint_cost = _cond_entropy(joint, pair_map)

    pushed: Joint = {}
    for z, w in joint.items():
        key = (f(z[0]), g(z[1]))
        pushed[key] = pushed.get(key, 0.0) + w

    led = Ledger(separate, joint_cost, mutual_information(joint), mutual_information(pushed))
    assert isclose(led.saving, led.predicted_saving, abs_tol=1e-12), "accounting identity"
    assert led.mutual_out <= led.mutual_in + 1e-12, "data-processing inequality"
    return led


if __name__ == "__main__":
    collapse = lambda _: 0
    shared = {(0, 0): 0.5, (1, 1): 0.5}
    independent = {(x, y): 0.25 for x in (0, 1) for y in (0, 1)}
    for name, law in (("shared lemma", shared), ("independent", independent)):
        led = compositional_ledger(law, collapse, collapse)
        print(f"{name:14s} separate={led.separate:.4f}  joint={led.joint:.4f} "
              f" saving={led.saving:.4f}  I_in={led.mutual_in:.4f}  I_out={led.mutual_out:.4f}")

"""
Algorithm 3 -- Bureaucratic Normalization with a Termination Certificate.

Derivations of the calculus Bur_n are pairs (u, c) in {0,1}^n x {0,1}^n: an
n-bit conclusion c and an n-bit bookkeeping vector u recording which of the n
independent inference blocks were performed in bureaucratic order.  Rule i
applies when u_i = 1 and sets u_i to 0.

The routine below normalizes a derivation under an arbitrary rule-selection
strategy while emitting a certificate: the sequence of rules fired, the strictly
decreasing weight measure that proves termination, and a check that the result
is (0, c) regardless of strategy.  Termination is guaranteed after exactly w(d)
steps, where w(d) is the number of bureaucratic blocks, hence at most n.

Complexity: O(n) rule firings, each O(1) with an explicit support list, so O(n)
overall; the fiber of any normal form has exactly 2^n elements, which is why the
fiber is never enumerated.
"""

from __future__ import annotations

from dataclasses import dataclass
from math import log, log2
from typing import Callable, List, Sequence, Tuple

Deriv = Tuple[Tuple[int, ...], Tuple[int, ...]]


@dataclass
class NormalizationCertificate:
    start: Deriv
    result: Deriv
    rules_fired: List[int]
    weight_trace: List[int]

    @property
    def steps(self) -> int:
        return len(self.rules_fired)

    def is_valid(self, n: int) -> bool:
        strictly_decreasing = all(
            b < a for a, b in zip(self.weight_trace, self.weight_trace[1:])
        )
        return (
            strictly_decreasing
            and self.weight_trace[-1] == 0
            and self.result == (tuple(0 for _ in range(n)), self.start[1])
            and self.steps <= n
        )


def weight(d: Deriv) -> int:
    """The strictly decreasing termination measure: number of bureaucratic blocks."""
    return sum(d[0])


def applicable_rules(d: Deriv) -> List[int]:
    return [i for i, ui in enumerate(d[0]) if ui == 1]


def fire(d: Deriv, i: int) -> Deriv:
    """Apply rule i; requires u_i = 1.  Conclusion is untouched."""
    u = list(d[0])
    assert u[i] == 1, "rule i is not applicable"
    u[i] = 0
    return (tuple(u), d[1])


def normalize(
    d: Deriv,
    select: Callable[[Sequence[int]], int] = lambda rules: rules[0],
) -> NormalizationCertificate:
    """Normalize under any rule-selection strategy, emitting a certificate."""
    start = d
    rules_fired: List[int] = []
    trace: List[int] = [weight(d)]
    while True:
        rules = applicable_rules(d)
        if not rules:
            return NormalizationCertificate(start, d, rules_fired, trace)
        i = select(rules)
        d = fire(d, i)
        rules_fired.append(i)
        trace.append(weight(d))


def normalization_cost_bits(n: int) -> float:
    """Bits destroyed by normalizing Bur_n under the uniform law: exactly n."""
    return log2(2 ** n)  # fibers all of size 2^n


def landauer_heat(n: int, k_b: float = 1.380649e-23, temperature: float = 300.0) -> float:
    return normalization_cost_bits(n) * k_b * temperature * log(2.0)


if __name__ == "__main__":
    n = 5
    start: Deriv = ((1, 0, 1, 1, 0), (1, 1, 0, 1, 0))
    for name, strategy in (("leftmost", lambda r: r[0]), ("rightmost", lambda r: r[-1])):
        cert = normalize(start, strategy)
        print(f"{name:10s} steps={cert.steps}  rules={cert.rules_fired} "
              f" weights={cert.weight_trace}  valid={cert.is_valid(n)}  nf={cert.result}")
    print(f"fiber size = 2^{n} = {2 ** n};  bits erased = {normalization_cost_bits(n):.0f};"
          f"  heat = {landauer_heat(n):.3e} J")
